insert into auth.identities (id, user_id, provider_id, identity_data, last_sign_in_at, created_at, updated_at, provider)
select gen_random_uuid(), u.id, u.email,
  jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true),
  now(), now(), now(), 'email'
from auth.users u where u.email like '%@demo.in';

update public.user_roles set role = 'admin' where user_id = 'a0000000-0000-4000-8000-000000000001';
